import bareImage from './castle-bare-data.mjs';
const NS='http://www.w3.org/2000/svg';
const svg=(markup,viewBox='0 0 1280 1908')=>{const e=document.createElementNS(NS,'svg');e.setAttribute('viewBox',viewBox);e.innerHTML=markup;return e};
const defaults={mantel:200,time:'sunset',season:'summer',weather:'clear',rug:'tiger',fire:true,shields:Array.from({length:4},()=>({pattern:'original',color:'#7b2027'}))};
const key='edge-castle-environment-v1';
export function initSettings(room,renderPieces){
 let config=structuredClone(defaults);try{const saved=JSON.parse(localStorage.getItem(key));if(saved){for(const k of ['time','season','weather','rug'])if(typeof saved[k]==='string')config[k]=saved[k];if(saved.mantel>=140&&saved.mantel<=300)config.mantel=saved.mantel;if(typeof saved.fire==='boolean')config.fire=saved.fire;if(Array.isArray(saved.shields)&&saved.shields.length===4)config.shields=saved.shields.map(s=>({pattern:['original','cross','chevron','tower','star','plain'].includes(s.pattern)?s.pattern:'original',color:/^#[0-9a-f]{6}$/i.test(s.color)?s.color:'#7b2027'}))}}catch{}
 const bare=new Image();bare.src=bareImage;bare.alt='';bare.className='bare-floor';room.append(bare);
 const rug=svg('','0 0 800 420');rug.classList.add('rug-art');room.append(rug);
 const tint=document.createElement('div');tint.className='room-light';room.append(tint);
 const glow=document.createElement('div');glow.className='fire-glow';room.append(glow);
 const flames=svg(`<defs><linearGradient id="flameColor" x2="0" y2="1"><stop stop-color="#ff7921"/><stop offset=".7" stop-color="#ffc34c"/><stop offset="1" stop-color="#fff5bf"/></linearGradient></defs>${Array.from({length:7},(_,i)=>`<path fill="url(#flameColor)" d="M${i*20} 100 Q${i*20-6} 74 ${i*20+4} 58 Q${i*20+15} 39 ${i*20+9} ${i%2?15:30} Q${i*20+33} 52 ${i*20+23} 73 Q${i*20+34} 91 ${i*20+21} 100Z"/>`).join('')}`,'0 0 160 110');flames.classList.add('flame-layer');room.append(flames);
 const shields=svg('');shields.classList.add('shield-art');room.append(shields);
 const weather=document.createElement('canvas');weather.width=640;weather.height=954;weather.className='window-effect';weather.setAttribute('aria-hidden','true');room.append(weather);const ctx=weather.getContext('2d');
 const dialog=document.createElement('dialog');dialog.id='roomSettings';dialog.innerHTML=`<button class="close" aria-label="Close room settings">×</button><h2>Make it your room</h2><p>Light, weather and details for your castle.</p><div class="settings-grid"><label>Time of day<select data-setting="time"><option value="sunrise">Sunrise</option><option value="day">Daylight</option><option value="sunset">Sunset</option><option value="night">Night</option></select></label><label>Season<select data-setting="season"><option value="spring">Spring</option><option value="summer">Summer</option><option value="autumn">Autumn</option><option value="winter">Winter</option></select></label><label>Weather outside<select data-setting="weather"><option value="clear">Clear</option><option value="rain">Rain</option><option value="snow">Snow</option></select></label><label>Rug<select data-setting="rug"><option value="tiger">Tiger rug</option><option value="persian">Burgundy Persian</option><option value="tartan">Forest tartan</option><option value="none">Bare stone</option></select></label><label class="wide"><input type="checkbox" data-setting="fire"> Flickering flames and firelight</label></div><h3>Room scale</h3><label>Mantel width: <output id="mantelReading"></output><input type="range" data-setting="mantel" min="140" max="300" step="10"></label><p class="settings-hint">The artwork has no measured room dimensions. A 2 m mantel is the starting assumption. Sculpture heights use the catalogue dimensions; changing this adjusts every piece together.</p><div class="shield-fields"><h3>Heraldic shields</h3><div class="settings-grid"><label>Shield<select id="shieldIndex"><option value="0">1 · Far left</option><option value="1">2 · Left centre</option><option value="2">3 · Right centre</option><option value="3">4 · Far right</option></select></label><label>Design<select id="shieldPattern"><option value="original">Original</option><option value="cross">Cross</option><option value="chevron">Chevron</option><option value="tower">Castle</option><option value="star">Star</option><option value="plain">Plain</option></select></label><label>Shield colour<input type="color" id="shieldColor"></label></div></div><p class="settings-hint">Changes preview immediately and save on this browser. Seasons colour the window view; rain and snow stay outside. Reduced-motion preferences are respected.</p><div class="actions"><button id="settingsDone">Done</button></div>`;document.body.append(dialog);
 const $=s=>dialog.querySelector(s);const save=()=>{try{localStorage.setItem(key,JSON.stringify(config))}catch{}};
 function paintRug(){bare.hidden=config.rug==='tiger';rug.style.display=['persian','tartan'].includes(config.rug)?'block':'none';if(config.rug==='persian')rug.innerHTML='<defs><pattern id="rugMotif" width="70" height="70" patternUnits="userSpaceOnUse"><path d="M35 5 60 35 35 65 10 35Z" fill="none" stroke="#caaa78" stroke-width="3"/><path d="M35 20 45 35 35 50 25 35Z" fill="#17403c"/></pattern></defs><rect x="5" y="5" width="790" height="410" rx="6" fill="#40201d"/><rect x="19" y="19" width="762" height="382" fill="#ae8960"/><rect x="32" y="32" width="736" height="356" fill="#6a2630"/><rect x="44" y="44" width="712" height="332" fill="url(#rugMotif)"/><path d="M400 75 560 210 400 345 240 210Z" fill="#bd9765"/><path d="M400 95 535 210 400 325 265 210Z" fill="#173d39"/><path d="M400 140 480 210 400 280 320 210Z" fill="#aa7151"/>';if(config.rug==='tartan')rug.innerHTML='<defs><pattern id="tartanWeave" width="100" height="100" patternUnits="userSpaceOnUse"><rect width="100" height="100" fill="#203c31"/><path d="M20 0V100M70 0V100M0 20H100M0 70H100" stroke="#172321" stroke-width="25"/><path d="M45 0V100M0 45H100" stroke="#8c2729" stroke-width="8"/><path d="M50 0V100M0 50H100" stroke="#c5aa72" stroke-width="2"/></pattern></defs><rect x="8" y="8" width="784" height="404" rx="8" fill="url(#tartanWeave)" stroke="#b39b71" stroke-width="8"/>'}
 const polygons=['103,232 165,251 161,302 139,337 111,308','315,313 383,314 378,367 351,405 320,371','719,347 779,351 777,403 749,435 723,402','978,292 1039,274 1037,335 1010,374 980,354'];
 const centers=[[135,280],[350,357],[749,389],[1009,325]];
 function paintShields(){shields.innerHTML=config.shields.map((s,i)=>{if(s.pattern==='original')return '';const [x,y]=centers[i];const mark=s.pattern==='cross'?`<path d="M${x-7} ${y-44}h14v31h28v14h-28v44h-14v-44h-28v-14h28Z" fill="#d8b878"/>`:s.pattern==='chevron'?`<path d="M${x-35} ${y+10}l35 -31 35 31v18l-35 -31 -35 31Z" fill="#d8b878"/>`:s.pattern==='tower'?`<path d="M${x-21} ${y+30}v-47h-5v-15h11v8h10v-8h10v8h10v-8h11v15h-5v47h-14v-17a7 7 0 0 0 -14 0v17Z" fill="#d8b878"/>`:s.pattern==='star'?`<path d="M${x} ${y-30}l8 21 23 1 -18 14 6 23 -19 -14 -19 14 6 -23 -18 -14 23 -1Z" fill="#d8b878"/>`:'';return `<defs><clipPath id="shieldClip${i}"><polygon points="${polygons[i]}"/></clipPath><linearGradient id="shieldShade${i}"><stop stop-color="#0007"/><stop offset=".4" stop-color="#ffffff18"/><stop offset="1" stop-color="#0005"/></linearGradient></defs><g clip-path="url(#shieldClip${i})"><polygon points="${polygons[i]}" fill="${s.color}"/>${mark}<polygon points="${polygons[i]}" fill="url(#shieldShade${i})"/></g><polygon points="${polygons[i]}" fill="none" stroke="#b99556" stroke-width="3"/>`}).join('')}
 function apply(){const lighting={sunrise:['brightness(1.05) saturate(.88)',1.03,'#f3b0a540'],day:['brightness(1.13) saturate(.88)',1.1,'#dce9ff20'],sunset:['none',1,'transparent'],night:['brightness(.56) saturate(.7)',.66,'#2d457875']}[config.time]||['none',1,'transparent'];room.style.setProperty('--room-filter',lighting[0]);room.style.setProperty('--piece-light',lighting[1]);room.style.setProperty('--room-tint',lighting[2]);room.dataset.mantel=config.mantel;$('#mantelReading').textContent=(config.mantel/100).toFixed(1)+' m';room.classList.toggle('still',!config.fire);glow.hidden=!config.fire;flames.style.display=config.fire?'block':'none';paintRug();paintShields();renderPieces();save()}
 dialog.querySelectorAll('[data-setting]').forEach(el=>{const k=el.dataset.setting;if(el.type==='checkbox')el.checked=config[k];else el.value=config[k];el.oninput=()=>{config[k]=el.type==='checkbox'?el.checked:k==='mantel'?Number(el.value):el.value;apply()}});
 function selectShield(){const s=config.shields[Number($('#shieldIndex').value)];$('#shieldPattern').value=s.pattern;$('#shieldColor').value=s.color}$('#shieldIndex').onchange=selectShield;for(const [selector,prop] of [['#shieldPattern','pattern'],['#shieldColor','color']])$(selector).oninput=()=>{config.shields[Number($('#shieldIndex').value)][prop]=$(selector).value;apply()};selectShield();
 // Reuse the existing inputs in focused editors, avoiding duplicated settings state.
 const mainGrid=dialog.querySelector('.settings-grid');
 const scaleHeading=dialog.querySelector('h3');
 const scaleLabel=dialog.querySelector('[data-setting="mantel"]').closest('label');
 const scaleHint=scaleLabel.nextElementSibling;
 const shieldFields=dialog.querySelector('.shield-fields');
 const title=dialog.querySelector('h2'),intro=title.nextElementSibling;
 const bottomHint=shieldFields.nextElementSibling;
 function openSection(section='all',index=0){
   title.textContent={all:'Make it your room',window:'Outside & lighting',rug:'Choose your rug',shield:'Heraldic shield '+(index+1),fire:'Firelight'}[section];
   intro.textContent={all:'You can also tap the objects directly in your room.',window:'Set the time, season and weather outside.',rug:'Choose a rug or leave the stone floor bare.',shield:'Customise this shield’s design and colour.',fire:'Set the movement and glow of the fire.'}[section];
   mainGrid.hidden=section==='shield';
   mainGrid.querySelectorAll('label').forEach(label=>{const k=label.querySelector('[data-setting]')?.dataset.setting;label.hidden=section!=='all'&&!(section==='window'&&['time','season','weather'].includes(k))&&!(section==='rug'&&k==='rug')&&!(section==='fire'&&k==='fire')});
   for(const e of [scaleHeading,scaleLabel,scaleHint])e.hidden=section!=='all';
   shieldFields.hidden=!['all','shield'].includes(section);
   $('#shieldIndex').closest('label').hidden=section==='shield';
   bottomHint.hidden=section!=='all';
   if(section==='shield'){$('#shieldIndex').value=String(index);selectShield()}
   dialog.showModal();
 }
 function hotspot(label,box,section,index){const b=document.createElement('button');b.className='room-hotspot';b.setAttribute('aria-label',label);b.title=label;b.style.cssText=`left:${box[0]}%;top:${box[1]}%;width:${box[2]}%;height:${box[3]}%`;b.onclick=()=>openSection(section,index);room.append(b)}
 hotspot('Change window weather, season and lighting',[0,23,9,38],'window');
 hotspot('Change rug',[11,81,76,16],'rug');
 [[7,11.7,7.5,7],[23.5,16.1,7.5,6.5],[55.4,17.5,7,6.5],[75.3,14,7.5,7]].forEach((box,i)=>hotspot('Customise shield '+(i+1),box,'shield',i));
 hotspot('Change fire flicker',[31,66,17,8],'fire');
 document.querySelector('#settings').onclick=()=>openSection('all');$('.close').onclick=()=>dialog.close();$('#settingsDone').onclick=()=>dialog.close();
 const reduce=matchMedia('(prefers-reduced-motion: reduce)');let last=0;
 function draw(t){requestAnimationFrame(draw);if(document.hidden||t-last<50)return;last=t;ctx.clearRect(0,0,640,954);ctx.save();ctx.beginPath();ctx.moveTo(0,252);ctx.lineTo(41,229);ctx.lineTo(58,303);ctx.lineTo(59,589);ctx.lineTo(0,599);ctx.closePath();ctx.clip();const seasonColors={spring:'#9bbd6355',summer:'#d3b85b22',autumn:'#be681e66',winter:'#d5e7f277'};ctx.globalAlpha=.3;ctx.fillStyle=seasonColors[config.season]||'#0000';ctx.fillRect(0,220,65,390);if(config.time==='night'){ctx.fillStyle='#071b4ba0';ctx.fillRect(0,220,65,390)}else if(config.time==='sunrise'){ctx.fillStyle='#ffb5a866';ctx.fillRect(0,220,65,390)}else if(config.time==='day'){ctx.fillStyle='#bde3ff44';ctx.fillRect(0,220,65,390)}ctx.globalAlpha=1;if(!reduce.matches){const sec=t/1000;if(config.weather==='snow'){ctx.fillStyle='#fff';for(let i=0;i<42;i++){const x=(i*17+Math.sin(sec+i)*4)%65,y=225+(i*29+sec*(9+i%5))%380;ctx.globalAlpha=.45+i%4*.15;ctx.beginPath();ctx.arc(x,y,1+i%3*.4,0,Math.PI*2);ctx.fill()}}if(config.weather==='rain'){ctx.strokeStyle='#b7dbef99';ctx.lineWidth=.6;for(let i=0;i<32;i++){const x=(i*13-sec*10)%75,y=220+(i*31+sec*160)%400;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+14);ctx.stroke()}}if(config.season==='autumn'&&config.weather==='clear'){ctx.fillStyle='#d38e2daa';for(let i=0;i<8;i++){const x=(i*19+Math.sin(sec*.6+i)*8)%65,y=300+(i*39+sec*8)%290;ctx.fillRect(x,y,2,3)}}}ctx.restore()}
 apply();requestAnimationFrame(draw);
}
